INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-LANCOME-LA-VIE-EST-BELLE','Lancôme','La Vie Est Belle Eau de Parfum 100 ml','العطور','العطور','حلاوة دافئة تناسب مناسبة خاصة أو مساءً هادئًا. يضفي السوسن نعومة بودرية، وتمنح الفانيلا والسكر الرائحة ملمسًا حلوًا، فيما يضيف الباتشولي عمقًا ترابيًا.','{"nameAr":"لانكوم لا في إي بيل · أو دو بارفان نسائي 100 مل","tagline":"حلاوة دافئة يوازنها السوسن","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["السوسن بطابع بودري","الفانيلا والسكر المغزول","الباتشولي بطابعه الترابي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"La Vie Est Belle Eau de Parfum 100 ml","tagline":"Warm sweetness balanced by iris","description":"A warm, sweet fragrance for a special evening. Iris brings a powdery softness; vanilla and spun sugar add sweetness, while patchouli gives it an earthy depth.","benefits":["Powdery iris","Vanilla and spun sugar","Earthy patchouli"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9900,9900,0,'/media/catalog/TSPF-LANCOME-LA-VIE-EST-BELLE-dc04f8751357.webp','https://www.lancome-usa.com/fragrance/fragrance-by-collection/la-vie-est-belle/la-vie-est-belle-eau-de-parfum/100606.html','Lancôme',24,1,1) ON CONFLICT(id) DO NOTHING;
