INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-VERSACE-EROS-EDT','Versace','Eros Eau de Toilette 100 ml','العطور','العطور','يناسب طلعة تحب فيها رائحة واضحة وحيوية. يمنح النعناع والليمون والتفاح بداية باردة ومنعشة، ثم يهدأ العطر مع الفانيلا والتونكا والأخشاب.','{"nameAr":"فيرساتشي إيروس · أو دو تواليت رجالي 100 مل","tagline":"انتعاش النعناع مع دفء الفانيلا","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["نعناع وليمون وتفاح أخضر","إبرة الراعي ولمسة عنبرية","فانيلا وتونكا وأخشاب الأرز"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Eros Eau de Toilette 100 ml","tagline":"Cool mint and warm vanilla","description":"An upbeat choice for a night out. Mint, lemon and apple feel bright and cool, then vanilla, tonka and woods give the scent a warmer finish.","benefits":["Mint, lemon and green apple","Geranium and an ambery touch","Vanilla, tonka and cedarwoods"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9000,9000,0,'/media/catalog/TSPF-VERSACE-EROS-EDT-3c0bd4dbf2ef.webp','https://www.versace.com/by/en/men/accessories/fragrances-body-care/eros/eros-edt-100-ml/R740010-R100MLS_RNUL.html','Versace',24,1,1) ON CONFLICT(id) DO NOTHING;
