INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-GUCCI-FLORA-MAGNOLIA','Gucci','Flora Gorgeous Magnolia Eau de Parfum 100 ml','العطور','العطور','عطر زهري خفيف الإحساس يناسب النهار أو موعدًا مسائيًا. تمنح الماغنوليا الرائحة طابعًا زهريًا، ويضيف التوت حلاوة فاكهية، فيما يوازن الباتشولي النهاية بلمسة ترابية.','{"nameAr":"غوتشي فلورا غورجس ماغنوليا · أو دو بارفان نسائي 100 مل","tagline":"ماغنوليا مشرقة ولمسة توت","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["الماغنوليا","نفحة توت الندى","الباتشولي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Flora Gorgeous Magnolia Eau de Parfum 100 ml","tagline":"Bright magnolia with a touch of berries","description":"An airy floral for daytime or an evening date. Magnolia leads, a dewberry accord adds juicy sweetness, and patchouli grounds the finish.","benefits":["Magnolia essence","Dewberry accord","Patchouli essence"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',10000,10000,0,'/media/catalog/TSPF-GUCCI-FLORA-MAGNOLIA-5eb593d7ebc8.webp','https://www.gucci.com/uk/en_gb/pr/beauty/fragrances/fragrances-for-women/gucci-flora/gucci-flora-gorgeous-magnolia-100ml-eau-de-parfum-p-757363999990099','Gucci',24,1,1) ON CONFLICT(id) DO NOTHING;
