INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-YSL-Y-EDP','Yves Saint Laurent','Y Eau de Parfum 100 ml','العطور','العطور','رائحة مرتبة تنتقل معك من النهار إلى المساء. تعطي الميرمية وإبرة الراعي إحساسًا منعشًا في البداية، ثم تصبح الرائحة أدفأ مع الأخشاب والتونكا.','{"nameAr":"إيف سان لوران واي · أو دو بارفان رجالي 100 مل","tagline":"انتعاش عشبي على قاعدة خشبية","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["الميرمية المنعشة","إبرة الراعي","الأخشاب الدافئة وحبوب التونكا"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Y Eau de Parfum 100 ml","tagline":"A fresh aromatic scent over warm woods","description":"A polished scent that moves easily from day to evening. Sage and geranium start bright and aromatic before warm woods and tonka come through.","benefits":["Fresh sage","Geranium","Warm woods and tonka bean"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9600,9600,0,'/media/catalog/TSPF-YSL-Y-EDP-7f13fb6ecb49.webp','https://www.yslbeauty.com/int/fragrance/fragrance-for-him/y/y--eau-de-parfum/3614272050358.html','Yves Saint Laurent',24,1,1) ON CONFLICT(id) DO NOTHING;
