INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-ARMANI-STRONGER-WITH-YOU-EDT','Emporio Armani','Stronger With You Eau de Toilette 100 ml','العطور','العطور','يناسب أمسية باردة أو جلسة قريبة. يفتح الهيل والفلفل الوردي الرائحة، ثم تظهر الميرمية. وتمنح الكستناء والفانيلا العطر نهاية حلوة ودافئة مع لمسة مسك.','{"nameAr":"إمبوريو أرماني سترونغر ويذ يو · أو دو تواليت رجالي 100 مل","tagline":"كستناء وفانيلا لأمسية دافئة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["الهيل والفلفل الوردي وأوراق البنفسج","الميرمية","الفانيلا والكستناء والمسك"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Stronger With You Eau de Toilette 100 ml","tagline":"Chestnut and vanilla for a warm evening","description":"A comforting scent for a cool evening. Cardamom and pink pepper lead into sage, then sweet chestnut, vanilla and musk settle into a warm finish.","benefits":["Cardamom, pink pepper and violet leaves","Sage","Vanilla, sweet chestnut and musk"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9900,9900,0,'/media/catalog/TSPF-ARMANI-STRONGER-WITH-YOU-EDT-59329744e684.webp','https://www.armani.com/en-us/emporio-armani/eau-de-toilette-stronger-with-you-100-ml-cod-L5617100-NLP-100ML/','Emporio Armani',24,1,1) ON CONFLICT(id) DO NOTHING;
